            raise PlanFailure('tree root indegree')
        for v in participants:
            if v != root and indeg[v] != 1:
                raise PlanFailure(('tree indegree',v,indeg[v]))
        seen={root}; stack=[root]
        while stack:
            x=stack.pop()
            for y in adj[x]:
                if y not in seen:
                    seen.add(y); stack.append(y)
